// @FIGURE_CODE_BEGIN
const W = 600, H = 450;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Clickable background to clear highlights
const bgRect = draw.rect(W, H).fill('transparent');
bgRect.on('click', clearHighlight);

// Layer groups to maintain z-index order
const layerOrigEdges = draw.group();
const layerEdgeGraphEdges = draw.group();
const layerOrigNodes = draw.group();
const layerEdgeNodes = draw.group();
const layerAnnotations = draw.group();

const nodeData = {
  1: { x: 470, y: 180 },
  2: { x: 140, y: 120 },
  3: { x: 300, y: 70 },
  4: { x: 220, y: 360 },
  5: { x: 90,  y: 260 },
  6: { x: 450, y: 360 }
};

const edgeData = [
  { id: '1/3', u: 1, v: 3 },
  { id: '1/4', u: 1, v: 4 },
  { id: '1/5', u: 1, v: 5 },
  { id: '1/6', u: 1, v: 6 },
  { id: '2/3', u: 2, v: 3 },
  { id: '2/5', u: 2, v: 5 },
  { id: '4/5', u: 4, v: 5 },
  { id: '4/6', u: 4, v: 6 }
];

// Edge nodes sit at the midpoints of original edges
const enData = edgeData.map(e => ({
  id: e.id,
  u: e.u,
  v: e.v,
  x: (nodeData[e.u].x + nodeData[e.v].x) / 2,
  y: (nodeData[e.u].y + nodeData[e.v].y) / 2
}));

// Connect edge nodes if they share an original vertex
const egeData = [];
for (let i = 0; i < enData.length; i++) {
  for (let j = i + 1; j < enData.length; j++) {
    const en1 = enData[i];
    const en2 = enData[j];
    if (en1.u === en2.u || en1.u === en2.v || en1.v === en2.u || en1.v === en2.v) {
      egeData.push({
        id: en1.id + '-' + en2.id,
        u: en1.id,
        v: en2.id,
        x1: en1.x, y1: en1.y,
        x2: en2.x, y2: en2.y
      });
    }
  }
}

// Visual references for updates
const visuals = {
  origEdges: {},
  origNodes: {},
  edgeNodes: {},
  edgeGraphEdges: {}
};

// 1. Draw Original Edges
edgeData.forEach(e => {
  const line = layerOrigEdges.line(nodeData[e.u].x, nodeData[e.u].y, nodeData[e.v].x, nodeData[e.v].y)
    .stroke({ width: 3, color: '#222', linecap: 'round' });

  // Invisible wider line for easier clicking
  const hitLine = layerOrigEdges.line(nodeData[e.u].x, nodeData[e.u].y, nodeData[e.v].x, nodeData[e.v].y)
    .stroke({ width: 24, color: 'transparent', linecap: 'round' })
    .css('cursor', 'pointer');

  hitLine.on('click', (ev) => { ev.stopPropagation(); selectMapping(e.id); });
  hitLine.on('mouseenter', (ev) => showTooltip('Original edge (' + e.id.replace('/', ', ') + ')', ev))
         .on('mouseleave', () => hideTooltip());

  visuals.origEdges[e.id] = { line, hitLine, u: e.u, v: e.v };
});

// 2. Draw Edge Graph Edges
egeData.forEach(e => {
  const line = layerEdgeGraphEdges.line(e.x1, e.y1, e.x2, e.y2)
    .stroke({ width: 2, color: '#444', linecap: 'round' });
  visuals.edgeGraphEdges[e.id] = { line, u: e.u, v: e.v };
});

// 3. Draw Original Nodes
Object.keys(nodeData).forEach(k => {
  const id = parseInt(k);
  const nd = nodeData[id];
  const group = layerOrigNodes.group();
  group.circle(32).center(nd.x, nd.y).fill('#e07a5f').stroke({ width: 2, color: '#222' });
  group.text(k).center(nd.x, nd.y).font({ family: 'sans-serif', size: 16, anchor: 'middle' }).dy(1);
  visuals.origNodes[id] = { group };
});

// 4. Draw Edge Nodes
enData.forEach(en => {
  const group = layerEdgeNodes.group().css('cursor', 'pointer');
  const bg = group.circle(34).center(en.x, en.y).fill('#92d0cc').stroke({ width: 2, color: '#222' });
  group.text(en.id).center(en.x, en.y).font({ family: 'sans-serif', size: 14, anchor: 'middle' }).dy(1.5);

  group.on('click', (ev) => { ev.stopPropagation(); selectMapping(en.id); });
  group.on('mouseenter', (ev) => showTooltip('Edge-node ' + en.id.replace('/', ','), ev))
       .on('mouseleave', () => hideTooltip());

  visuals.edgeNodes[en.id] = { group, bg, u: en.u, v: en.v };
});

// 5. Draw Annotations
const text1 = layerAnnotations.text("Add new node at each original edge")
  .center(W/2, H - 20).font({ family: 'sans-serif', size: 15, style: 'italic' }).opacity(0);
const text2 = layerAnnotations.text("Connect new nodes if original edges shared node")
  .center(W/2, H - 20).font({ family: 'sans-serif', size: 15, style: 'italic' }).opacity(0);

// Interaction State
let currentPhase = 0;
let selectedMapping = null;

function clearHighlight() {
  if (selectedMapping !== null) {
    selectedMapping = null;
    updateView();
  }
}

function selectMapping(id) {
  selectedMapping = (selectedMapping === id) ? null : id;
  updateView();
}

function updateView() {
  const phase = currentPhase;
  const h = selectedMapping;
  const dur = 300; // ms transition

  // Base opacities defined by the current construction phase
  let oeOp = 1, onOp = 1, egeOp = 0, enOp = 0;
  if (phase === 1) { enOp = 1; }
  else if (phase === 2) { enOp = 1; egeOp = 1; oeOp = 0.25; onOp = 0.25; }
  else if (phase === 3) { enOp = 1; egeOp = 1; oeOp = 0; onOp = 0; }

  const dimOp = 0.15; // Opacity for de-emphasized elements during a highlight

  // 1. Update Original Edges
  Object.keys(visuals.origEdges).forEach(id => {
    const vis = visuals.origEdges[id];
    if (h) {
      if (id === h) {
        vis.line.animate(dur).opacity(1); // Force reveal if clicked in Phase 3
        vis.line.stroke({ width: 7, color: '#e07a5f' });
      } else {
        vis.line.animate(dur).opacity(phase === 3 ? 0 : dimOp);
        vis.line.stroke({ width: 3, color: '#222' });
      }
    } else {
      vis.line.animate(dur).opacity(oeOp);
      vis.line.stroke({ width: 3, color: '#222' });
    }
    // Prevent clicking ghost edges when original graph is hidden
    vis.hitLine.css('pointer-events', phase === 3 ? 'none' : 'auto');
  });

  // 2. Update Original Nodes
  Object.keys(visuals.origNodes).forEach(k => {
    const id = parseInt(k);
    const vis = visuals.origNodes[id];
    if (h) {
      const activeEn = enData.find(en => en.id === h);
      if (activeEn && (activeEn.u === id || activeEn.v === id)) {
        vis.group.animate(dur).opacity(1); // Force reveal endpoints
      } else {
        vis.group.animate(dur).opacity(phase === 3 ? 0 : dimOp);
      }
    } else {
      vis.group.animate(dur).opacity(onOp);
    }
  });

  // 3. Update Edge Nodes
  Object.keys(visuals.edgeNodes).forEach(id => {
    const vis = visuals.edgeNodes[id];
    if (h) {
      if (id === h) {
        // Prevent showing the teal node early if highlighting in Phase 0
        vis.group.animate(dur).opacity(enOp > 0 ? 1 : 0);
        vis.bg.stroke({ width: 4, color: '#e07a5f' });
      } else {
        vis.group.animate(dur).opacity(enOp > 0 ? dimOp : 0);
        vis.bg.stroke({ width: 2, color: '#222' });
      }
    } else {
      vis.group.animate(dur).opacity(enOp);
      vis.bg.stroke({ width: 2, color: '#222' });
    }
    // Prevent interacting with invisible nodes in Phase 0
    vis.group.css('pointer-events', phase === 0 ? 'none' : 'auto');
  });

  // 4. Update Edge Graph Edges
  Object.keys(visuals.edgeGraphEdges).forEach(id => {
    const vis = visuals.edgeGraphEdges[id];
    if (h) {
      if (vis.u === h || vis.v === h) {
        vis.line.animate(dur).opacity(egeOp > 0 ? 1 : 0);
        vis.line.stroke({ width: 4, color: '#222' });
      } else {
        vis.line.animate(dur).opacity(egeOp > 0 ? dimOp : 0);
        vis.line.stroke({ width: 2, color: '#444' });
      }
    } else {
      vis.line.animate(dur).opacity(egeOp);
      vis.line.stroke({ width: 2, color: '#444' });
    }
  });

  // 5. Update Annotations
  text1.animate(dur).opacity(phase === 1 && !h ? 1 : 0);
  text2.animate(dur).opacity(phase === 2 && !h ? 1 : 0);
}

// --- Step Player Logic ---
const demoSteps = [
  { phase: 0, narration: "We start with a standard undirected graph consisting of 6 nodes (orange) and 8 edges." },
  { phase: 1, narration: "To build the edge graph, we first place a new node (teal) at the midpoint of every original edge." },
  { phase: 2, narration: "Next, we draw a connection between any two new nodes if their underlying original edges met at the same original vertex." },
  { phase: 3, narration: "Removing the original structure reveals the final edge graph. Try clicking any node to highlight which original edge it came from and why it connects to its neighbors." }
];
let currentStep = 0;

function updateStepUI() {
  document.getElementById('demoNarration').textContent = demoSteps[currentStep].narration;
  document.getElementById('stepLabel').textContent = `Step ${currentStep + 1} / 4`;

  const targetPhase = demoSteps[currentStep].phase;
  const radios = document.getElementsByName('phase');
  for (let i = 0; i < radios.length; i++) {
    if (parseInt(radios[i].value) === targetPhase) {
      radios[i].checked = true;
    }
  }
}

window.prevStep = function() {
  if (currentStep > 0) {
    currentStep--;
    currentPhase = demoSteps[currentStep].phase;
    selectedMapping = null;
    updateStepUI();
    updateView();
  }
};

window.nextStep = function() {
  if (currentStep < demoSteps.length - 1) {
    currentStep++;
    currentPhase = demoSteps[currentStep].phase;
    selectedMapping = null;
    updateStepUI();
    updateView();
  }
};

window.setPhase = function(p) {
  currentPhase = p;
  currentStep = p; // Keep step player synced if user manually clicks a radio
  selectedMapping = null;
  updateStepUI();
  updateView();
};

// Initialize
updateStepUI();
updateView();
window.__markRendered();
// @FIGURE_CODE_END

